__NUXT_JSONP__("/svet/stat/jihoafricka-republika/ceny", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q){return {data:[{tabsLoad:{tabWhatToSee:e,tabPrice:e,tabPeople:e,tabTrip:e,tabContact:e,tabHotel:e,tabNeighboring:e,tabVideos:h,tabArticles:h,tabWallSockets:i,tabChains:j},place:[{tld:".za",name:"Jihoafrická republika",area:1221037,population:59622350,slug:k,id_continent:f,information_chatgpt:"\u003Cp\u003EV Jihoafrické republice najdete několik národních parků a přírodních rezervací, kde můžete vidět některá z největších zvířat na světě, jako jsou sloni, lvi a nosorožci. Země má také nádherné pláže, krásné pohoří a úchvatné vodopády, které stojí za návštěvu.\u003C\u002Fp\u003E\n\u003Cp\u003EJihoafrická republika je rovněž známá svými kulturními a historickými památkami, jako jsou tradiční africké vesnice, muzea apartheidu a historická města, jako je například Kapstadt. Země má také mnoho vynikajících restaurací a vinic, kde si můžete vychutnat místní speciality a vína.\u003C\u002Fp\u003E\n\u003Cp\u003EKromě toho je Jihoafrická republika také ideálním místem pro outdoorové aktivity, jako je například surfování, horolezectví, potápění a safari. Můžete si také pronajmout auto a projet se po známé Garden Route, což je malebná cesta vedoucí podél pobřeží.\u003C\u002Fp\u003E\n\u003Cp\u003EJihoafrická republika je bohatá na přírodní, kulturní a historické bohatství. Můžete zde prožít skvělou dovolenou, plnou poznávání a zážitků. Pokud se chystáte na cestu do této země, určitě se nebudete nudit!\u003C\u002Fp\u003E",currency_code:"ZAR",currency_name:"Jihoafrický rand",money_prices:[{name:"Taxi (cena za km)",value:l,date_update:b},{name:"Hlavní jídlo",value:100,date_update:b},{name:"Chleba",value:m,date_update:b},{name:"Mléko",value:15,date_update:b},{name:"Voda (500ml)",value:l,date_update:b},{name:"Espresso",value:18,date_update:b},{name:"Zmrzlina (jeden kopeček)",value:7,date_update:b},{name:"Pivo",value:n,date_update:b},{name:"Krabička cigaret",value:45,date_update:b},{name:"Bic Mac",value:n,date_update:b},{name:"Coca Cola (500ml)",value:m,date_update:b}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"112",date_update:a},{name:"Policie",value:"10111",date_update:a},{name:"Hasiči",value:o,date_update:a},{name:"Zdravotnická záchranná služba",value:o,date_update:a},{name:"Turistická policie",value:"0861 874 911",date_update:a},{name:"Horská záchranná služba",value:"0800 005 133",date_update:a}],phone_prefix:"+27",coordinates:[{latitude:"-30.5595",longitude:"22.9375"}],people_religion:[{name:"Křesťanství",value:"79%",date_update:c},{name:"Islám",value:p,date_update:c},{name:"Hinduismus",value:p,date_update:c},{name:"Tradiční africká náboženství",value:"0.3%",date_update:c},{name:"Bez vyznání",value:"15%",date_update:c},{name:"Jiné",value:"3.7%",date_update:c}],people_nationality:[{name:"Černoši",value:"80,9%",date_update:c},{name:"Bílí",value:"8,4%",date_update:c},{name:"Kolorovaní",value:"8,8%",date_update:c},{name:"Indové",value:"2,5%",date_update:c},{name:"Jiní",value:"0,7%",date_update:c}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Jihoafrické republiky je potřeba mít platný cestovní pas, občanský průkaz nestačí.",date_update:a},{name:"Cestovní pas",value:"Pro vstup do Jihoafrické republiky je potřeba mít platný cestovní pas.",date_update:a},{name:"Vízum",value:"Pro vstup do Jihoafrické republiky je pro většinu občanů Evropské unie (včetně ČR) potřeba mít vízum. Podrobné informace o vízové povinnosti lze získat na webových stránkách Jihoafrické republiky nebo na konzulátech Jihoafrické republiky v dané zemi.",date_update:a},{name:"Očkování",value:"Pro vstup do Jihoafrické republiky je povinnost očkování nebo negativní PCR test (maximálně 72 hodin před odletem) platná pro všechny cestující ve věku 12 let a více. Doporučené očkování je proti hepatitidě A a B, tetanu, spalničkám, případně doporučené očkování proti žluté zimnici v závislosti na cestovní destinaci v Jihoafrické republice.",date_update:a},{name:"Cestovní pojištění",value:"Cestovní pojištění není povinné, nicméně se doporučuje kvůli možným zdravotním rizikům spojeným s cestováním a pobytu v Jihoafrické republice. Některé země mohou vyžadovat předložení potvrzení o cestovním pojištění při vstupu do země.",date_update:a},{name:"Bezpečnostní situace",value:"Jihoafrická republika má vysokou míru kriminality a bezpečnostní situace může být problematická, zejména v určitých částech země. Je doporučeno být obezřetný a dodržovat základní bezpečnostní opatření, jako je například nechávat cennosti v hotelu, nechodit sama po tmě, vyhýbat se opuštěným a nebezpečným oblastem atd.",date_update:a},{name:"Další informace",value:"Při cestování do Jihoafrické republiky je důležité dodržovat zákony a zvyklosti země. Například se nedoporučuje fotografovat vojenské objekty, nebo náboženské symboly. Je také důležité být obezřetný při setkání s neznámými lidmi a v případě nejasností neváhejte kontaktovat místní úřady nebo konzulát své země.",date_update:a}],type_place:q,id_image_cover:g,id_image_hero:g,id_city_main:2436,affiliate:[{name:"booking",value:e}],mpz:"ZA",alerts:d,zoom:[{google:i,booking:f}],ids_neighboring_countries:[{id:35},{id:159},{id:160},{id:213},{id:249}],organization:d,apps:d,links:d,information_author:d,seo_tags:d,language_phrases:d,wall_sockets:d,id:247,facts_place:d,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2023-12-27T17:07:31.480426+00:00"}],imagePlace:[{id:g,name:k,source:"\u002Fworld\u002Fstates\u002F",type:q,author:"pixabay.com",created_at:"2023-05-03T20:14:00.749527+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:f,slug:"afrika",name:"Afrika",area:30370000,population:1340000000,population_density:44.12,number_states:54,information_chatgpt:"\u003Cp\u003EAfrika je největší kontinent na Zemi a rozkládá se na ploše přesahující 30 milionů kilometrů čtverečních. Nachází se zde více než 50 zemí a žije zde více než 1,3 miliardy lidí. \u003C\u002Fp\u003E\n\u003Cp\u003EJižní Afrika, Egypt, Maroko a Keňa patří mezi nejoblíbenější turistické cíle v Africe. V Jihoafrické republice se můžete podívat na slavné Krugerův národní park a sledovat zde život zvířat v jejich přirozeném prostředí. Egypt je zase proslulý svými pyramidami, které se nacházejí v Gíze. V Maroku můžete navštívit tradiční trhy, zatímco v Keni se můžete setkat s Masajským kmenem a podívat se na úžasnou přírodu.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má bohatou historii a kulturu. První lidé, kteří se usadili v Africe, byli loveckým a sběračským národem. Poté se v této oblasti objevily první civilizace, jako je Kúšská říše, Egyptská říše nebo Království Aksum. Afrika byla také kolonizována evropskými mocnostmi a toto období mělo značný dopad na dnešní politickou situaci na kontinentu.\u003C\u002Fp\u003E\n\u003Cp\u003EJe důležité zmínit, že Afrika má velké množství jazyků a kultur. Zahrnuje mnoho různých národů a etnických skupin, a to má vliv na různorodost obyvatelstva a kultury. Nejrozšířenějším jazykem je arabština, která se mluví především v severní Africe a v některých částech západní Afriky. Dalšími důležitými jazyky jsou svahilština, francouzština, portugalština, angličtina a mnoho dalších.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má také nádhernou přírodu. Nachází se zde nejvyšší hora světa, Kilimandžáro, která se nachází na území Tanzanie a Keňy. Kromě toho se v Africe nachází také největší pouště na světě, Sahara, a největší prales, Kongský prales. Na tomto kontinentě můžete vidět také mnoho zvířat, jako jsou sloni, lvi, gepardi, zebry a mnoho dalších druhů. V Africe se také nachází několik nejvýznamnějších řek světa, jako je Nil, Kongo, Niger a Zambezi.\u003C\u002Fp\u003E\u003Cp\u003EAfrika je bohužel také známá pro své problémy. Mnoho zemí se potýká s chudobou, nedostatkem potravin a vody, nemocemi a válečnými konflikty. Mnoho afrických zemí závisí na zemědělství a rybolovu, což však často není dostatečně výnosné, aby zabezpečilo potřeby obyvatelstva. Kromě toho jsou některé země v Africe trvale postižené extrémními přírodními katastrofami, jako jsou sucha, povodně a bouře.\u003C\u002Fp\u003E\n\u003Cp\u003ENa druhou stranu se v Africe také nachází mnoho lidí, kteří se snaží změnit situaci a zlepšit životy svých spoluobčanů. Vznikají neziskové organizace, které se snaží pomáhat při řešení těchto problémů a zlepšovat kvalitu života v mnoha afrických zemích. Zároveň se v posledních letech objevují nové možnosti pro ekonomický růst a rozvoj, jako jsou technologické start-upy a zahraniční investice.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika je fascinující kontinent, který nabízí mnoho zážitků a zároveň v sobě ukrývá mnoho výzev. Pokud se rozhodnete navštívit Afriku, můžete se těšit na krásnou přírodu, bohatou kulturu a nezapomenutelné zážitky. Je však také důležité být obezřetný a připravený na místní podmínky, protože některé oblasti mohou být nebezpečné kvůli konfliktům nebo zločinnosti.\u003C\u002Fp\u003E",coordinates:[{latitude:1.650801,longitude:17.371642}],type_place:"continent",id_image_cover:f,id_image_hero:f,zoom:[{google:2,booking:j}],information_author:d,seo_tags:d,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00"}]}],fetch:{},mutations:[]}}("05-2023","06-2021","12-2021",null,true,5,278,0,4,3,"jihoafricka-republika",10,12,30,"10177","1%","state")));